(()=>{'use strict';
const root=document.getElementById('asiqpai-v2'),main=root.querySelector('#aq-main'),feedback=root.querySelector('#aq-feedback'),picker=root.querySelector('#aq-screen-picker'),nav=root.querySelector('.aq-nav');
const data=ASIQPAI_DATA,screens=data.screens,e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({screen:'music',history:[],fields:{},track:'MID',takes:{MID:false,BACK:false,ADLIBS:false},mix:{MID:{volume:100,pan:0,width:0,mute:false,solo:false,preset:'MID · PREMIUM',fx:{TUNE:false,EQ:true,COMP:true,REVERB:true,DELAY:false},bypass:false,offset:0,key:'A',scale:'Minor',tuneMode:'AUTO'},BACK:{volume:76,pan:0,width:40,mute:false,solo:false,preset:'BACK · WIDE',fx:{TUNE:false,EQ:true,COMP:true,REVERB:true,DELAY:false},bypass:false,offset:0,key:'A',scale:'Minor',tuneMode:'AUTO'},ADLIBS:{volume:82,pan:12,width:55,mute:false,solo:false,preset:'ADLIBS · SPACE',fx:{TUNE:false,EQ:true,COMP:true,REVERB:true,DELAY:true},bypass:false,offset:0,key:'A',scale:'Minor',tuneMode:'AUTO'}},lyrics:'',wallet:false,sampleGenerated:false,sampleCount:1,sampleFavourite:false,sampleTab:0,playing:false,musicIndex:0,dirty:false,exported:false,compare:'После FX',external:'',beatLevel:60,ai:false});let state=fresh(),timer=null,seconds=0;
const current=()=>screens.find(s=>s.id===state.screen)||screens[0];const mix=()=>state.mix[state.track];const fieldKey=l=>state.screen+':'+l;const value=(l,fallback='')=>state.fields[fieldKey(l)]??fallback;
const say=(text,error=false)=>{feedback.setAttribute('role',error?'alert':'status');feedback.textContent=text;};
const button=(label,to,style='primary',disabled=false)=>`<button type="button" class="aq-${style}" data-action="${e(to)}" ${['↶','◀','▶','Ⅱ','▶|'].includes(label)?'aria-label="'+({'↶':'Режим воспроизведения','◀':'Предыдущий трек','▶':'Воспроизвести демопревью','Ⅱ':'Пауза демопревью','▶|':'Следующий трек'}[label])+'"':''} ${disabled?'disabled':''}>${e(label)}</button>`;
const wave=()=>`<div class="aq-wave" data-playing="${state.playing}" aria-label="Демонстрационная форма волны">${Array.from({length:40},(_,i)=>`<i style="height:${6+Math.abs(Math.sin(i*1.7))*40}px"></i>`).join('')}</div>`;
const art=(key='gold',large=false)=>`<div class="aq-art ${e(key)} ${large?'aq-art-large':''}" aria-hidden="true">/ /</div>`;
const notice=(title,text,status='info')=>`<div class="aq-notice ${status}"><strong>${e(title)}</strong><p>${e(text)}</p></div>`;
const card=(title,meta,to,key='gold')=>`<div class="aq-card" data-search-content="${e(title+' '+meta)}">${art(key)}<div class="aq-card-copy"><strong>${e(title)}</strong><small>${e(meta)}</small></div><span class="aq-chevron" aria-hidden="true">›</span><button type="button" class="aq-card-action" data-action="${e(to)}" aria-label="Открыть ${e(title)}"></button></div>`;
function textField(v,i){const id='aq-f-'+i;let val=value(v.label,v.value);if(v.label==='Текст / телесуфлёр')val=state.lyrics;if(v.label==='Характер обработки')val=mix().preset;if(v.label==='Режим TUNE')val=mix().tuneMode;if(v.label==='Тональность'&&state.screen==='tune')val=mix().key;if(v.label==='Лад'&&state.screen==='tune')val=mix().scale;if(v.label==='Громкость бита')val=state.beatLevel;if(v.label==='WIDTH / DOUBLE')val=mix().width;if(v.label==='Сдвиг вокала, секунды')val=mix().offset;
const attrs=`id="${id}" data-field="${e(v.label)}"`;let input='';if(v.kind==='textarea')input=`<textarea ${attrs} placeholder="${e(v.placeholder||'')}">${e(val)}</textarea>`;else if(v.kind==='select')input=`<select ${attrs}>${(v.options||[v.value]).map(x=>`<option ${x===val?'selected':''}>${e(x)}</option>`).join('')}</select>`;else if(v.kind==='range')input=`<input ${attrs} type="range" min="${v.min??0}" max="${v.max??100}" value="${Number(val)}">`;else input=`<input ${attrs} type="${v.kind==='number'?'number':v.kind==='search'?'search':'text'}" ${v.kind==='search'?`placeholder="Название или артист" value="${e(val)}"`:`value="${e(val)}"`} ${v.kind==='number'?`min="${v.min??0}" max="${v.max??240}" step="${v.step??1}"`:''}>`;
return `<label class="aq-field" for="${id}"><span>${e(v.label)}${v.kind==='range'?` <output>${e(val)} ${e(v.unit||'')}</output>`:''}</span>${input}</label>`;}
const trackSelect=()=>`<div class="aq-tabs" role="group" aria-label="Выбранная вокальная дорожка">${['MID','BACK','ADLIBS'].map(t=>`<button type="button" data-track="${t}" aria-pressed="${state.track===t}">${t}${state.takes[t]?' ✓':''}</button>`).join('')}</div>`;
function mixer(){const m=mix();return `<section class="aq-mixer"><div class="aq-row aq-between"><strong>${state.track}</strong><div class="aq-mini-toggles">${['mute','solo'].map(k=>`<button type="button" data-mix-toggle="${k}" aria-pressed="${m[k]}">${k==='mute'?'Mute':'Solo'}</button>`).join('')}</div></div>${['volume','pan'].map(k=>`<label class="aq-field"><span>${k==='volume'?'Громкость дорожки':'PAN'} <output>${m[k]}${k==='volume'?'%':''}</output></span><input type="range" data-mix="${k}" aria-label="${k==='volume'?'Громкость дорожки':'PAN'}" min="${k==='pan'?-100:0}" max="100" value="${m[k]}"></label>`).join('')}</section>`;}
function wallet(status){const connected=state.wallet||status==='connected'||status==='loading'||status==='error';const amount=status==='connected'?'125.50':'—';return `<div class="aq-balance-panel"><span class="aq-eyebrow">AVAILABLE BALANCE</span><strong>${amount} <span style="font-size:18px">ASIQ</span></strong><small>${status==='loading'?'Обновляем баланс…':status==='error'?'Баланс не получен':connected?'Демокошелёк подключён':'Подключите TON-кошелёк'}</small><div class="aq-detail-row"><span>Сеть</span><span>TON Network</span></div>${connected?'<div class="aq-meta">EQ…DEMO · пример, не адрес кошелька</div>':''}</div>`;}
function renderItem(v,i){switch(v.type){case'button':return button(v.label,v.to,v.style,v.disabled);case'body':return `<p class="aq-body">${e(v.text)}</p>`;case'section':return `<h2>${e(v.text)}</h2>`;case'pill':return `<span class="aq-pill">${e(v.text)}</span>`;case'card':return card(v.title,v.meta,v.to,v.art);case'field':return textField(v,i);case'notice':return notice(v.title,v.text,v.status);case'row':return `<div class="aq-detail-row"><span>${e(v.left)}</span><span>${e(v.right)}</span></div>`;case'wave':return wave();case'art':return art(v.art,true);case'steps':return `<div class="aq-steps"><strong>${v.step} / 4</strong><span>Бит → Голос → FX → WAV</span></div>`;
case'player':{const title=state.selectedTrack||v.title;return `<div class="aq-player">${art('gold',true)}<span class="aq-eyebrow">ASIQPAI ORIGINAL</span><div class="aq-row aq-between"><h2>${e(title)}</h2><button type="button" data-action="@music-like" aria-label="Добавить в избранное" aria-pressed="${!!state.musicLiked}">${state.musicLiked?'♥':'♡'}</button></div><p class="aq-meta">${e(state.selectedTrack?'ASIQPAI · TRACK':v.artist)}</p><label class="aq-field"><span>Позиция <output>0:00 / ${v.duration}</output></span><input aria-label="Позиция трека" type="range" min="0" max="78" value="0" data-progress="true"></label><div class="aq-player-controls">${button('↶','@mode','ghost')}${button('◀','@prev','secondary')}${button(state.playing?'Ⅱ':'▶','@play','primary')}${button('▶|','@next','secondary')}</div></div>`;}
case'tabs':return `<div class="aq-tabs" role="group" aria-label="${e(v.values.join(', '))}">${v.values.map((x,k)=>`<button type="button" data-tab="${k}" aria-pressed="${k===(state.screen==='sample-library'?state.sampleTab:v.selected)}">${e(x)}</button>`).join('')}</div>`;
case'rack':return `<div class="aq-track-rack">${['MID','BACK','ADLIBS'].map(t=>`<div class="aq-lane ${t===state.track?'active':''}"><div class="aq-row aq-between"><button class="aq-track-name" type="button" data-track="${t}" aria-pressed="${t===state.track}">${t} <small>${{MID:'Основной вокал',BACK:'Бэки / даблы',ADLIBS:'Вставки / выкрики'}[t]}</small></button><span class="aq-pill">${state.takes[t]?'READY':'EMPTY'}</span></div><div class="aq-rack-meta">${['mute','solo'].map(k=>`<button type="button" data-rack="${t}:${k}" aria-pressed="${state.mix[t][k]}">${k==='mute'?'M':'S'}</button>`).join('')}<span>VOL ${state.mix[t].volume}%</span><span>PAN ${state.mix[t].pan}</span></div>${state.takes[t]?wave():'<div class="aq-empty-wave">Дубль ещё не добавлен</div>'}</div>`).join('')}</div>`;
case'track-select':return trackSelect();case'mixer':return mixer();
case'analysis':return `<div class="aq-analysis"><span class="aq-eyebrow">BEAT ANALYSIS / ДЕМОЗНАЧЕНИЯ</span><div class="aq-analysis-grid">${[['BPM',state.fields['analysis:BPM']||'122'],['KEY',state.fields['analysis:Тональность']||'A'],['SCALE',state.fields['analysis:Лад']||'Minor'],['CONFIDENCE','Low']].map(([k,v])=>`<div><small>${k}</small><strong>${e(v)}</strong></div>`).join('')}</div></div>`;
case'timer':return `<div class="aq-timer" id="aq-timer">00:00</div><p class="aq-meta">Дорожка ${state.track} · демозапись</p>`;
case'teleprompter':return `<div class="aq-teleprompter" aria-label="Текст телесуфлёра" style="font-size:${Number(state.fields['teleprompter:Размер текста'])||26}px">${e(state.lyrics||'Добавь текст куплета, чтобы читать его здесь во время записи.')}</div>`;
case'upload':return `<div class="aq-upload"><span class="aq-eyebrow">${state.track} / UPLOAD</span><label class="aq-field"><span>Вокальный файл, до 25 МБ</span><input type="file" accept="audio/*" data-vocal-file="true"></label><small>Выбранный файл проверяется локально; звук не отправляется на сервер.</small></div>`;
case'ai-clean':return `<label class="aq-toggle"><span>AI CLEAN <small>демопереключатель</small></span><input type="checkbox" data-ai="true" ${state.ai?'checked':''}></label><button type="button" class="aq-ghost" data-action="ai-unavailable">Как выглядит недоступный AI CLEAN?</button>`;
case'fx-rack':return `<section class="aq-fx"><div class="aq-eyebrow">FX / ${state.track}</div><div class="aq-fx-grid">${Object.entries(mix().fx).map(([k,on])=>`<button type="button" data-fx="${k}" aria-pressed="${on}"><strong>${k}</strong><small>${on?'ON':'OFF'}</small></button>`).join('')}</div><button type="button" class="aq-secondary" data-mix-toggle="bypass" aria-pressed="${mix().bypass}">BYPASS ALL ${mix().bypass?'ON':'OFF'}</button><p class="aq-meta">BYPASS временно отключает обработку и сохраняет выбранные эффекты.</p></section>`;
case'summary':return `<div class="aq-tile">${['MID','BACK','ADLIBS'].map(t=>`<div class="aq-detail-row"><span>${t}${state.takes[t]?' ✓':' —'}</span><span>${e(state.mix[t].preset)}</span></div>`).join('')}<div class="aq-detail-row"><span>Длительность демодубля</span><span>00:12</span></div></div>`;
case'compare':return `<div class="aq-tabs" role="group" aria-label="Сравнить обработку">${['После FX','BYPASS / исходник'].map(x=>`<button type="button" data-compare="${e(x)}" aria-pressed="${state.compare===x}">${e(x)}</button>`).join('')}</div>`;
case'sample-results':return Array.from({length:state.sampleCount},(_,i)=>card('Melodic stem / 0'+(i+1),`${state.fields['samples:BPM']||122} BPM · ${state.fields['samples:Длина']||'4 такта'} · WAV`,'sample-detail',i%2?'gold':'sage')).join('');
case'sample-library':return !state.sampleGenerated?notice('Пока нет сэмплов','Создай первый мелодический stem.'):state.sampleTab===1&&!state.sampleFavourite?notice('Нет избранного','Отметь понравившийся вариант звездой.'):card('Melodic stem / 01',`${state.fields['samples:BPM']||122} BPM · ${state.sampleFavourite?'★ избранное':'AI SAMPLE'}`,'sample-detail','sage');
case'wallet':return wallet(v.status);
case'community-links':return `<div class="aq-community-links">${[['ASIQPAI','https://asiqpai.site/'],['Telegram Community','https://t.me/asiqpaihub'],['YouTube Community','https://youtube.com/@asiqpai'],['TikTok Community','https://tiktok.com/@asiqpai'],['Instagram Community','https://instagram.com/asiqpai/']].map(([name,url])=>card(name,url.replace('https://',''),'@external:'+url,'sage')).join('')}</div>`;
case'external-preview':return `<div class="aq-tile"><p>${e(state.external||'Официальная страница ASIQPAI')}</p><a class="aq-external-link" href="${e(state.external||'https://asiqpai.site/')}" target="_blank" rel="noopener noreferrer">Открыть официальную страницу ↗</a></div>`;
case'skeleton':return `<div class="aq-skeleton" aria-label="Загрузка">${[65,100,80].map(w=>`<i style="width:${w}%"></i>`).join('')}</div>`;default:return '';}}
function render(){clearInterval(timer);const s=current();main.dataset.screen=s.id;picker.value=s.id;feedback.textContent='';feedback.setAttribute('role','status');root.querySelector('#aq-screen-description').textContent=s.name+' / '+s.sub;main.innerHTML=`<div class="aq-eyebrow">${e(s.nav.toUpperCase())} / ASIQPAI</div><h1>${e(s.title)}</h1><p class="aq-sub">${e(s.sub)}</p>${s.items.map(renderItem).join('')}`;nav.innerHTML=[['Music','music','♫'],['Library','library','▱'],['Studio','studio','≋'],['Wallet',state.wallet?'wallet-connected':'wallet','◈'],['Community','community','◉']].map(([name,to,icon])=>`<button type="button" data-go="${to}" ${s.nav===name?'aria-current="page"':''}><span class="aq-nav-symbol" aria-hidden="true">${icon}</span>${name==='Studio'?'AI Studio':name}</button>`).join('');root.querySelector('#aq-back').disabled=!state.history.length;if(s.id==='recording'){seconds=0;timer=setInterval(()=>{seconds++;const t=main.querySelector('#aq-timer');if(t)t.textContent=Math.floor(seconds/60).toString().padStart(2,'0')+':'+(seconds%60).toString().padStart(2,'0');if(seconds>=180){clearInterval(timer);go('take');say('Достигнут лимит 3 минуты. Демоостановка записи.');}},1000);}}
function go(id,history=true){if(!screens.some(s=>s.id===id))return;if(history&&id!==state.screen)state.history.push(state.screen);state.screen=id;state.playing=false;render();}
function handleAction(action,b){if(action==='@play'){state.playing=!state.playing;main.querySelectorAll('.aq-wave').forEach(n=>n.dataset.playing=String(state.playing));if(state.screen==='music')b.textContent=state.playing?'Ⅱ':'▶';else b.textContent=state.playing?'Ⅱ Пауза демопревью':'Прослушать демопревью';say('Показано состояние плеера. Аудио не подключено.');return;}
if(action.startsWith('@select-track:')){state.selectedTrack=action.slice(14);go('music');return;}if(action==='@next'||action==='@prev'){state.musicIndex=(state.musicIndex+(action==='@next'?1:-1)+data.tracks.length)%data.tracks.length;state.selectedTrack=data.tracks[state.musicIndex];render();return;}if(action==='@mode'){say('Режим демоплеера: повтор / по порядку.');return;}if(action==='@music-like'){state.musicLiked=!state.musicLiked;b.textContent=state.musicLiked?'♥':'♡';b.setAttribute('aria-pressed',String(state.musicLiked));return;}
if(action==='@keep-take'||action==='@upload-demo'){state.takes[state.track]=true;state.dirty=true;go('record');say('Демонстрационный дубль '+state.track+' добавлен.');return;}
if(action==='@to-process'||action==='@to-mix'){go(state.takes.MID?(action==='@to-process'?'process':'mix-confirm'):'no-mid');return;}if(action==='@select-mid'){state.track='MID';go('record');return;}
if(action==='@analysis'){go('beat');say('Демонстрационные параметры анализа применены.');return;}if(action==='@clear-lyrics'){state.lyrics='';go('lyrics');say('Текст очищен.');return;}
if(action==='@apply-tune'){mix().fx.TUNE=true;go('process');say('TUNE применён к дорожке '+state.track+'.');return;}if(action==='@apply-fit'){go('process');say('Показано применение AI Fit. Настоящее аудио не изменяется.');return;}
if(action==='@apply-slicer'){const a=Number(value('Начало, секунды',0)),z=Number(value('Конец, секунды',12));if(!Number.isFinite(a)||!Number.isFinite(z)||a<0||z<=a||z>12){say('Выбери интервал 0–12 секунд, конец позже начала.',true);return;}mix().slice={start:a,end:z};go('process');say('Демонстрационный фрагмент применён. Исходник сохранён в сессии.');return;}
if(action==='@generate-samples'){const prompt=value('Что хотите услышать?','').trim(),bpm=Number(value('BPM',122));if(!prompt){say('Опиши мелодию перед генерацией.',true);return;}if(bpm<70||bpm>180){say('BPM должен быть от 70 до 180.',true);return;}state.sampleCount=value('Количество вариантов','1 вариант')==='3 варианта'?3:1;go('sample-wait');return;}
if(action==='@sample-favourite'){state.sampleFavourite=!state.sampleFavourite;b.textContent=state.sampleFavourite?'★ В избранном':'Добавить в избранное';b.setAttribute('aria-pressed',String(state.sampleFavourite));return;}if(action==='@sample-download'){say('Макет скачивания WAV. Настоящий файл не создаётся.');return;}
if(action==='@wallet-connect'){state.wallet=true;go('wallet-connected');say('Демонстрационное подключение. Реальный TON-кошелёк не подключён.');return;}if(action==='@wallet-disconnect'){state.wallet=false;go('wallet');return;}if(action==='@wallet-home'){go(state.wallet?'wallet-connected':'wallet');return;}
if(action.startsWith('@external:')){state.external=action.slice(10);go('external-link');return;}
if(action==='@finish'){state.dirty=false;state.exported=true;go('music');say('Демосессия завершена. Настоящий WAV в прототипе не создавался.');return;}if(action==='@leave'){state.dirty=false;state.takes={MID:false,BACK:false,ADLIBS:false};go('music');return;}
if(state.screen==='sample-wait'&&action==='sample-results')state.sampleGenerated=true;if(action==='export-done')state.exported=true;go(action);}
root.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.review==='reset'){clearInterval(timer);state=fresh();render();return;}if(b.dataset.review==='system'){const s=root.querySelector('#aq-system');s.hidden=!s.hidden;if(!s.hidden)s.scrollIntoView({block:'start'});return;}if(b.id==='aq-back'){const prev=state.history.pop();if(prev)go(prev,false);return;}if(b.dataset.go){if(current().nav==='Studio'&&(state.dirty||state.screen==='recording')&&!state.exported&&screens.find(s=>s.id===b.dataset.go)?.nav!=='Studio'){go('exit');return;}go(b.dataset.go);return;}if(b.dataset.track){state.track=b.dataset.track;render();return;}if(b.dataset.mixToggle){mix()[b.dataset.mixToggle]=!mix()[b.dataset.mixToggle];render();return;}if(b.dataset.rack){const [t,k]=b.dataset.rack.split(':');state.mix[t][k]=!state.mix[t][k];render();return;}if(b.dataset.fx){mix().fx[b.dataset.fx]=!mix().fx[b.dataset.fx];b.setAttribute('aria-pressed',String(mix().fx[b.dataset.fx]));b.querySelector('small').textContent=mix().fx[b.dataset.fx]?'ON':'OFF';return;}if(b.dataset.compare){state.compare=b.dataset.compare;render();say('Выбрано: '+state.compare+'. Аудио не подключено.');return;}if(b.dataset.tab!==undefined){const k=Number(b.dataset.tab);if(['library','instrumentals'].includes(state.screen)){go(k?'instrumentals':'library');return;}state.sampleTab=k;render();return;}if(b.dataset.action)handleAction(b.dataset.action,b);});
root.addEventListener('input',ev=>{const n=ev.target;if(n.dataset.field){const l=n.dataset.field;state.fields[fieldKey(l)]=n.value;if(l==='Текст / телесуфлёр')state.lyrics=n.value;if(l==='Характер обработки')mix().preset=n.value;if(l==='Режим TUNE')mix().tuneMode=n.value;if(l==='Тональность'&&state.screen==='tune')mix().key=n.value;if(l==='Лад'&&state.screen==='tune')mix().scale=n.value;if(l==='Громкость бита')state.beatLevel=Number(n.value);if(l==='WIDTH / DOUBLE')mix().width=Number(n.value);if(l==='Сдвиг вокала, секунды')mix().offset=Number(n.value);if(n.type==='range'){const output=n.parentElement.querySelector('output');if(output)output.textContent=n.value+(l==='BPM'?' BPM':l==='Размер текста'?' px':'%');}if(l==='Размер текста'){const p=main.querySelector('.aq-teleprompter');if(p)p.style.fontSize=n.value+'px';}if(n.type==='search'){let count=0;main.querySelectorAll('[data-search-content]').forEach(c=>{c.hidden=!c.dataset.searchContent.toLowerCase().includes(n.value.toLowerCase());if(!c.hidden)count++;});say(count?'Найдено: '+count:'Ничего не найдено. Измени запрос.');}}if(n.dataset.mix){mix()[n.dataset.mix]=Number(n.value);n.parentElement.querySelector('output').textContent=n.value+(n.dataset.mix==='volume'?'%':'');}if(n.dataset.ai)state.ai=n.checked;if(n.dataset.progress)n.parentElement.querySelector('output').textContent='0:'+String(n.value).padStart(2,'0')+' / 1:18';});
root.addEventListener('change',ev=>{const n=ev.target;if(n.dataset.vocalFile){const file=n.files?.[0];if(!file)return;if(file.size>25*1024*1024||(!file.type.startsWith('audio/')&&!/\.(wav|mp3|m4a|aac|ogg|flac)$/i.test(file.name))){go('upload-error');return;}state.uploadName=file.name;say('Файл выбран: '+file.name+'. Обработка и загрузка на сервер не запускаются.');}});
picker.innerHTML=screens.map(s=>`<option value="${e(s.id)}">${e(s.name)}</option>`).join('');picker.addEventListener('change',()=>go(picker.value));
root.querySelector('#aq-system').innerHTML=`<button type="button" class="review-system-close" data-review="system">Закрыть UI Kit</button><h2>ASIQPAI / MVP-aligned UI Kit</h2><p>Один визуальный язык для Music, Library, Vocal AI, Samples и TON Wallet.</p><div class="system-grid"><div><h3>Цвета и контраст</h3>${Object.entries(data.tokens).map(([k,c])=>`<div class="system-swatch"><i style="background:${c}"></i><span>${e(k)} / ${c}</span></div>`).join('')}</div><div class="aq-app"><h3>Контролы</h3>${button('Основное действие','studio')}${button('Вторичное действие','studio','secondary')}${button('Записать MID','recording','record')}${button('Недоступно','studio','primary',true)}${notice('Сессия не сохранится','Экспортируй WAV перед закрытием.')}${notice('Баланс не получен','Не подменяй ошибку нулевым балансом.','error')}</div><div class="aq-app"><h3>Студийные компоненты</h3>${trackSelect()}${wave()}${mixer()}<h3>Навигация</h3><p class="aq-meta">Music / Library / AI Studio / Wallet / Community</p></div></div>`;
root.querySelector("#aq-format").addEventListener("change",ev=>{root.querySelector(".review-layout").classList.toggle("desktop",ev.target.value==="desktop");});render();})();
